const body = $input.first().json.body ?? $input.first().json;
const staticData = $getWorkflowStaticData('global');
staticData.streaks = staticData.streaks || {};
staticData.reports = staticData.reports || {};

const alerts = [];
for (const r of (body.results || [])) {
  const key = r.url;
  const isBroken = r.outcome === 'broken';
  const prev = staticData.streaks[key] || 0;
  const streak = isBroken ? prev + 1 : 0;
  staticData.streaks[key] = streak;
  if (streak >= 3) {
    alerts.push({ url: r.url, reason: r.reason, streak, references: r.references });
  }
}

let reportUrl = '';
if (alerts.length) {
  // Reports self-prune after 30 days so static data does not grow forever.
  const cutoff = Date.now() - 30 * 24 * 60 * 60 * 1000;
  for (const [token, report] of Object.entries(staticData.reports)) {
    if (new Date(report.createdAt).getTime() < cutoff) delete staticData.reports[token];
  }

  const token = (typeof crypto !== 'undefined' && crypto.randomUUID)
    ? crypto.randomUUID()
    : Array.from({ length: 32 }, () => Math.floor(Math.random() * 16).toString(16)).join('');
  staticData.reports[token] = { alerts, summary: body.summary, createdAt: new Date().toISOString() };
  reportUrl = 'https://n8n.kjnet.us/webhook/indienodes-member-health-report?token=' + token;
}

return [{ json: { alerts, summary: body.summary, reportUrl } }];

const query = $input.first().json.query || {};
const token = (query.token || '').toString();
const staticData = $getWorkflowStaticData('global');
const report = (staticData.reports || {})[token];

const esc = (v) => (v === undefined || v === null ? '' : v.toString())
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

// Trimmed port of indienodes-app's scripts/n8n/build_workflows.py review_style
// (the CSS Webring - Review Action v2 uses for its own status pages), so a
// tapped Gotify alert looks like the rest of the IndieNodes admin surface
// instead of a bare JSON dump.
const style = `
:root{
  color-scheme:light dark;
  --bg:#f7f4ee;--bg-elevated:rgba(255,255,255,.82);--text:#221f1a;
  --muted:#6b6558;--border:rgba(228,221,207,.9);
  --accent:#b5502f;--accent-hover:#963f24;--danger:#bf3b45;--warning:#b7791f;
  --shadow:0 24px 80px rgba(70,52,31,.16);
  --audio:#3b82f6;--game:#22c55e;--comic:#a855f7;--text-type:#f59e0b;
}
*{box-sizing:border-box}
html{min-height:100%;background:var(--bg)}
body{
  min-height:100vh;margin:0;padding:clamp(1rem,3vw,2.5rem);
  background:
    radial-gradient(circle at 10% 4%,rgba(181,80,47,.18),transparent 28rem),
    radial-gradient(circle at 92% 12%,rgba(45,90,130,.15),transparent 30rem),
    var(--bg);
  color:var(--text);font-family:Karla,Inter,ui-sans-serif,system-ui,-apple-system,sans-serif;
  font-size:16px;line-height:1.55;
}
a{color:var(--accent);text-underline-offset:.18em}
a:hover{color:var(--accent-hover)}
.shell{position:relative;width:min(760px,100%);margin:0 auto;padding-top:clamp(1rem,7vh,4rem)}
.brand{display:inline-flex;align-items:center;gap:.75rem;margin:0 0 1rem;color:var(--text);text-decoration:none}
.brand-mark{display:grid;grid-template-columns:repeat(2,8px);gap:4px;transform:rotate(45deg)}
.brand-mark i{display:block;width:8px;height:8px;border-radius:3px}
.brand-mark i:nth-child(1){background:var(--audio)}
.brand-mark i:nth-child(2){background:var(--game)}
.brand-mark i:nth-child(3){background:var(--comic)}
.brand-mark i:nth-child(4){background:var(--text-type)}
.brand-copy{display:flex;flex-direction:column;line-height:1.1}
.brand-copy strong{font-family:"Space Grotesk",Inter,ui-sans-serif,system-ui,sans-serif;font-size:1.05rem}
.brand-copy small{margin-top:.2rem;color:var(--muted);font-size:.72rem;font-weight:700;letter-spacing:.11em;text-transform:uppercase}
.panel{position:relative;overflow:hidden;border:1px solid var(--border);border-radius:24px;background:var(--bg-elevated);box-shadow:var(--shadow);backdrop-filter:blur(22px)}
.panel::before{content:"";position:absolute;inset:0 0 auto;height:3px;background:linear-gradient(90deg,var(--audio),var(--game),var(--comic),var(--text-type))}
.status-panel{padding:clamp(1.5rem,5vw,2.5rem)}
.status-panel h1{margin:0;font-family:"Space Grotesk",Inter,ui-sans-serif,system-ui,sans-serif;font-size:clamp(1.6rem,4vw,2.25rem);letter-spacing:-.03em}
.status-panel p:not(.eyebrow){margin:.7rem 0 0;color:var(--muted)}
.eyebrow{margin:0 0 .55rem;color:var(--muted);font-size:.73rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase}
.status-icon{display:grid;width:3rem;height:3rem;margin-bottom:1rem;place-items:center;border-radius:50%;background:rgba(107,101,88,.1);color:var(--muted);font-size:1.45rem;font-weight:900}
.status-panel.danger .status-icon{background:color-mix(in srgb,var(--danger) 14%,transparent);color:var(--danger)}
.status-panel.warning .status-icon{background:color-mix(in srgb,var(--warning) 16%,transparent);color:var(--warning)}
.section{padding:clamp(1.25rem,3.5vw,2rem);border-top:1px solid var(--border)}
.section-label{margin:0 0 .55rem;color:var(--muted);font-size:.73rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase}
.details{width:100%;border-collapse:separate;border-spacing:0;overflow:hidden;border:1px solid var(--border);border-radius:14px}
.details th,.details td{padding:.7rem .85rem;border-bottom:1px solid var(--border);text-align:left;vertical-align:top;font-size:.88rem}
.details tr:last-child th,.details tr:last-child td{border-bottom:0}
.details th{width:22%;color:var(--muted);font-size:.72rem;letter-spacing:.06em;text-transform:uppercase;background:rgba(255,255,255,.24)}
.details td{overflow-wrap:anywhere;font-weight:600}
.meta{margin:1rem 0 0;color:var(--muted);font-size:.8rem}
`;

const brand = '<a class="brand" href="https://indienodes.us/" target="_blank" rel="noopener">' +
  '<span class="brand-mark" aria-hidden="true"><i></i><i></i><i></i><i></i></span>' +
  '<span class="brand-copy"><strong>IndieNodes</strong><small>Link health report</small></span></a>';

function page(tone, iconChar, title, inner) {
  return '<!doctype html><html lang="en"><head><meta charset="utf-8">' +
    '<meta name="viewport" content="width=device-width,initial-scale=1">' +
    '<meta name="color-scheme" content="light dark"><title>IndieNodes link health</title>' +
    '<style>' + style + '</style></head><body><main class="shell">' + brand +
    '<article class="panel status-panel ' + tone + '">' +
    '<div class="status-icon" aria-hidden="true">' + iconChar + '</div>' +
    '<p class="eyebrow">Link health</p><h1>' + esc(title) + '</h1>' + inner +
    '</article></main></body></html>';
}

if (!report) {
  const body = page('warning', '!', 'Report not found or expired',
    '<p>This report link is invalid, or its report has already been pruned (reports are kept 30 days).</p>');
  return [{ json: { html: body } }];
}

const s = report.summary || {};
const rows = report.alerts.map((a) => {
  const refs = (a.references || []).map((r) => esc(r.memberFile) + ':' + esc(r.field)).join(', ');
  return '<tr><td>' + esc(a.url) + '</td><td>' + esc(a.reason) + '</td><td>' + esc(a.streak) +
    '</td><td>' + refs + '</td></tr>';
});

const summaryLine = [s.membersChecked, 'member(s) checked,', s.urlsChecked, 'URL(s):',
  s.healthy, 'healthy,', s.broken, 'broken,', s.warnings, 'warning(s).'].join(' ');

const inner =
  '<p>' + esc(summaryLine) + '</p>' +
  '<div class="section"><p class="section-label">Crossed the alert threshold</p>' +
  '<table class="details"><thead><tr><th>URL</th><th>Reason</th><th>Streak</th><th>Member</th></tr></thead>' +
  '<tbody>' + rows.join('') + '</tbody></table></div>' +
  '<p class="meta">Generated ' + esc(report.createdAt) + '. This link expires after 30 days.</p>';

const body = page('danger', '!', report.alerts.length + ' link(s) crossed the failure threshold', inner);
return [{ json: { html: body } }];

const staticData = $getWorkflowStaticData('global');
staticData.streaks = staticData.streaks || {};
const testUrl = 'https://example.invalid/simulated-fault';
// One below the real threshold (3) -- the shared 'Track streaks' node's own
// +1 is what crosses it, so this exercises the real alert/report/Gotify path
// end to end rather than bypassing it.
staticData.streaks[testUrl] = 2;

return [{ json: { body: {
  results: [{
    url: testUrl,
    outcome: 'broken',
    reason: 'simulated_test_fault',
    references: [{ memberFile: 'TEST-simulated.json', field: 'source_url' }]
  }],
  summary: { membersChecked: 0, urlsChecked: 1, healthy: 0, broken: 1, warnings: 0 }
} } }];
